def the_awl_and_the_double_hire(case, data):
    """F5 — Deut 15:16-18 — THE SLAVE WHO STAYS: two sayings at the term's end, the mutual love and the master's house, illness in either bars the rite; THE AWL a dispute (any tool / metal) with R. Ishmael's three circumventions; no judges, no doorpost — 'into the door' the SHORTENED row; THE UPPER RIGHT EAR by the labeled TRANSFER from the leper's (metzora by CALL); 'for ever' the master's lifetime with THE JUBILEE'S OVERRIDE on file (yovel by CALL) — serves_for_ever the case's STATUS; 'likewise' the gift, not the awl (the maidservant never pierced — the DISAGREES row resolved as data); the double hire resolved (the night's service the Canaanite maidservant); work_of_the_hand_blessed's second seat"""
    del P_[:]
    ask = case['ask']
    if ask == 'the_two_sayings':
        ink('15:16', '"and it shall be, if he SAYS to you: I will not go out from you" — "I will not go out" %s (Exodus 21:5, Job 31:34); the slave\'s ONE first-person word in the chapter %s (Moses\' "I command you" the other three); Exodus 21:5 "if the slave says, saying" %s' % (P('לא', 'אצא'), [(v, x) for v, x, m in [(v, x, m) for v in range(1, 24) for x, m in by[('Deut', 15, v)]] if m and '1cs' in m and m.startswith('HV')], words('Exod', 21, 5)[:4]))
        move('the Sifrei 121:1 (read whole at the reading); Kiddushin 22a:3-6, 15a:4-5 (read whole at the docket); cold_run_mishpatim (CALL) — the F1 table\'s FREE-AT-JUBILEE row %s' % (MP_F1[2],), "TWO SAYINGS — 'if he says' here and 'if the slave says, saying' at Exodus 21:5: he says and repeats (121:1; Kiddushin 22a:3-6 — says and repeats, while a slave, at the last peruta; 15a:4-5); the one who said once is not pierced")
        dat('the two sayings a DATA row (the_two_sayings — 121:1; Kiddushin 22a:3-6); the exam\'s person the slave who says it once — not pierced: exempt')
        return out("the two sayings (15:16) — 'if he says' here and 'if the slave says, saying' at Exodus 21:5: he says and repeats, while a slave, at the last peruta (the Sifrei 121:1; Kiddushin 22a:3-6): the slave who says it once exempt from the piercing", ['exempt'])
    if ask == 'the_awl_timing':
        ink('15:16-17', '"I will not go out from you … and he shall be your servant for ever" — "from you" at 15:16 %s; the term\'s end 15:12\'s "in the seventh year" %s' % ([x for x in W15(16) if x == 'מעמך'], W15(12)[10:13]))
        move('the Sifrei 121:2 (read whole at the reading); Kiddushin 22a:4-5 (read whole at the docket)', "TWO TIMES — at the end of six years and not at their beginning (121:2 — 'I will not go out from you': one who has served, not one about to); Kiddushin 22a:4-5 'at the last peruta' — the rite at the term's end, the slave still a slave: A DATA ROW the_awl_timing")
        dat('THE PARAMETER the_awl_timing (121:2 — at the term\'s end, not before; Kiddushin 22a:4-5 at the last peruta); the exam\'s person the master who pierces the slave in his first year — barred from it')
        return out("the awl's timing (15:16-17) — at the end of six years and not at their beginning, at the last peruta (the Sifrei 121:2; Kiddushin 22a:4-5): THE PARAMETER the_awl_timing; the master who pierces the slave in his first year barred from it", ['barred_from_it'])
    if ask == 'the_mutual_love':
        ink('15:16', '"because HE LOVES YOU AND YOUR HOUSE, because it is well with him with you" — "he loves you" the Torah\'s two %s (23:6 the other); "because it is well with him" %s (one seat; 23:17\'s escaped slave "where it is good for him" %s the kin); Exodus 21:5\'s "I love my master, my wife and my children" %s; Onkelos "the people of your house"' % (U('אהבך', books=T), P('כי', 'טוב', 'לו'), P('בטוב', 'לו'), words('Exod', 21, 5)[4:11]))
        move('the Sifrei 121:3 (read whole at the reading); Kiddushin 22a:7-8, 20a:14-15, 22a:10-13 (read whole at the docket); cold_run_mishpatim (CALL) — the F1 table; cold_run_holiness (CALL) — HO.wage(hire_kinds) = %s' % (V(HO_HIRE),), "THE LOVE MUTUAL AND THE MASTER'S HOUSE — 'because he loves you and your house': if he loves you and you do not love him, or you love him and he does not love you — he is not pierced (121:3; Kiddushin 22a:7-8: the mutual love and the master's house); Exodus 21:5's wife and children by CALL (mishpatim's F1); THE BOARD 'with you' — not fine bread against coarse, aged wine against new, soft bedding against straw: 'one who acquires a Hebrew slave acquires a master' (20a:14-15, 22a:10); THE FAMILY FED (22a:11-13 — 'he and his children with him', 'his wife shall go out with him')")
        dat('the mutual love a DATA row (the_mutual_love — 121:3; Kiddushin 22a:7-8; the board "with you"); the exam\'s person the slave who loves his master while the master does not love him — not pierced: exempt')
        return out("the mutual love (15:16) — 'because he loves you and your house': the love mutual, the master's house well with him (the Sifrei 121:3; Kiddushin 22a:7-8; the board 'with you' 20a:14-15 — 'one who acquires a Hebrew slave acquires a master'): the slave who loves his master while the master does not love him exempt from the piercing", ['exempt'])
    if ask == 'the_illness':
        ink('15:16', '"because it is WELL WITH HIM with you" — "well" %s; the condition\'s two persons in the clause (he, you)' % ([x for x in W15(16) if x == 'טוב'],))
        move('the Sifrei 121:4 (read whole at the reading); Kiddushin 22a:8-9 (read whole at the docket)', "ILLNESS IN EITHER BARS THE RITE — 'because it is well with him with you': if he is sick or you are sick, he is not pierced (121:4; Kiddushin 22a:8; both ill AN OPEN DILEMMA 22a:9 — the row recorded, no arm)")
        dat('the illness a DATA row (the_illness — 121:4; Kiddushin 22a:8-9 both ill an open dilemma); the exam\'s person the sick slave who says "I will not go out" — not pierced: exempt')
        return out("the illness (15:16) — if he is sick or you are sick he is not pierced; both ill an open dilemma (the Sifrei 121:4; Kiddushin 22a:8-9): the sick slave who says 'I will not go out' exempt from the piercing", ['exempt'])
    if ask == 'the_awl_tool':
        ink('15:17', '"then you shall take THE AWL" — "the awl" the Bible\'s TWO seats %s (Exodus 21:6 "with an awl", here "THE awl" with the article); the boring verb Exodus\'s alone %s' % (AWL, [(s, x) for s, x, _ in LEMT('7527')]))
        move('the Sifrei 122:1 (read whole at the reading); Kiddushin 21b:5-11 (read whole at the docket); Bekhorot 37b:10-11, 51a:15, Shevuot 4b:11 (read whole at the docket)', "THE AWL ANY TOOL OR METAL, A DISPUTE — 'and you shall take the awl': from where do I include the thorn, the glass, the reed's stalk? 'and you shall take' — anything taken in the hand; Rabbi: THE AWL, METAL alone (122:1); Kiddushin 21b:5-10 R. Yosei son of R. Yehuda's AMPLIFICATION-RESTRICTION (anything taken in the hand but a corrosive — the rival method, no code) against Rabbi's GENERAL-PARTICULAR-GENERAL (I6, checked in MIDDOT.md — metal); 'THE awl' the large awl by the article (21b:11); the four seats of the tools (Bekhorot 37b:10-11, 51a:15, Shevuot 4b:11)")
        dat('THE PARAMETER the_awl_tool (122:1 — any tool / metal; Kiddushin 21b:5-11 the two methods); the exam\'s person the master who pierces with a wooden thorn — barred from it on Rabbi\'s arm (metal alone), accepted on R. Yosei son of R. Yehuda\'s')
        return out("the awl's tool (15:17) — 'and you shall take the awl': anything taken in the hand (R. Yosei son of R. Yehuda, amplification-restriction) or metal alone (Rabbi, general-particular-general — I6) — the Sifrei 122:1; Kiddushin 21b:5-11: THE PARAMETER the_awl_tool; the master who pierces with a wooden thorn barred from it on Rabbi's arm", ['barred_from_it'])
    if ask == 'the_three_circumventions':
        ink('15:17', '"the awl" — the shelf\'s three seats of the method: the blood\'s dust (Leviticus 17:13 %s), the divorce\'s writ (24:1 ahead), the awl' % (words('Lev', 17, 13)[-5:],))
        move('the Sifrei 122:1 (read whole at the reading)', "R. ISHMAEL'S THREE PLACES WHERE THE HALAKHA CIRCUMVENTS SCRIPTURE (122:1 — the Torah said 'with dust' and the halakha with anything that grows plants; the Torah said 'a writ' and the halakha with anything detached; the Torah said 'an awl' and the halakha with anything): A DATA ROW the_three_circumventions — the code/data separation law's hardest case inside the spine: the ink names the tool, the answer sheet the class")
        dat('THE PARAMETER the_three_circumventions (122:1 — the blood\'s dust, the divorce\'s writ, the awl); the exam\'s person the scholar who reads the three as one method — accepted')
        return out("the three circumventions (15:17) — R. Ishmael's three places where the halakha circumvents Scripture: the blood's dust, the divorce's writ, the awl (the Sifrei 122:1 — the code/data separation law's hardest case inside the spine): the scholar who reads the three as one method accepted", ['accepted'])
    if ask == 'the_judges_and_the_door':
        ink('15:17', '"and put it through his ear AND INTO THE DOOR" — Exodus 21:6 "his master shall bring him to the judges, and bring him to the door or to the doorpost" %s: here NO judges, NO doorpost — one token shared in order %d; "the door" the Torah\'s four %s, "the doorpost" the Passover\'s and the frontlets\' %s' % (words('Exod', 21, 6), TWIN['15:17 vs Exod 21:6'], U('הדלת', 'ובדלת', 'דלת', 'הדלתות', 'בדלת', books=T), U('המזוזה', 'המזוזת', 'המזוזות', 'מזוזת', 'מזוזות', books=T)))
        move('the Sifrei 122:3, 122:7 (read whole at the reading); Kiddushin 22b:1-3 (read whole at the docket); cold_run_mishpatim (CALL) — the F1 table\'s three rows; the PROBES at Exodus 21:2, 21:8, Leviticus 25:10 %s' % (MP_PROBES,), "THE JUDGES PRESENT, THE DOOR — Exodus 21:6's 'to the judges' by CALL (mishpatim's own verse); here 'into the door' — no judges, no doorpost named: THE READBACK'S SHORTENED ROW (122:3 the judges; 122:7 through the ear into the door); Kiddushin 22b:1-3 through the ear until the door, the door upright and attached, not the doorpost (22b:4-5 the ear's and the door's homilies)")
        dat('the judges and the door a DATA row (the_judges_and_the_door — Exodus 21:6 by CALL; the SHORTENED row 15:16-17); the exam\'s person the master who pierces at the upright door before the judges — accepted')
        return out("the judges and the door (15:17) — Exodus 21:6's 'to the judges … the door or the doorpost' by CALL; here 'into the door' alone — the SHORTENED row (the Sifrei 122:3, 122:7; Kiddushin 22b:1-3 the door upright and attached): the master who pierces at the upright door before the judges accepted", ['accepted'])
    if ask == 'the_ear':
        ink('15:17', '"and put it through HIS EAR" — "his ear" %s; Leviticus 14:14\'s leper "the ridge of the RIGHT ear" the kin; the priest\'s blemish at Leviticus 21:17-23' % ([x for x in W15(17) if 'אזנ' in x],))
        move('the Sifrei 122:5-6 (read whole at the reading); Kiddushin 15a:1, 21b:7, 21b:12 (read whole at the docket); Bekhorot 37b:12-14 (read whole at the docket); cold_run_metzora (CALL — THE TRANSFER taught by the Sifrei 122:5-6 and Kiddushin 15a, labeled) — MZ.eighth(members) = %s; cold_run_priesthood (CALL) — PR.blemish(bald) = %s' % (V(MZ_MEMBERS), V(PR_BALD)), "THE UPPER RIGHT EAR — 'his ear': 'ear' is said here and 'ear' is said of the leper (Leviticus 14:14): as there the right ear, so here the right ear (122:5 — I2, checked in MIDDOT.md: THE TRANSFER taught by the Sifrei and by Kiddushin 15a:1, the exemplar the leper's right ear by CALL to metzora.eighth); THE UPPER EAR through the cartilage (122:6; Kiddushin 21b:7, 21b:12) BECAUSE A PRIEST-SLAVE IS NOT PIERCED LEST HE BE BLEMISHED — 'and he shall return to his own family' (Bekhorot 37b:12-14 the twin: the lobe against the cartilage); the priest's blemish by CALL")
        dat('THE PARAMETER the_ear (122:5-6 — the upper right ear by the leper\'s; the transfer\'s edge release_firstborn -> metzora labeled with its teachers); the exam\'s person the master who pierces the left ear — barred from it')
        return out("the ear (15:17) — 'his ear': the right ear by 'ear'/'ear' with the leper's (the Sifrei 122:5; Kiddushin 15a:1 — the TRANSFER taught, metzora by CALL, labeled), the upper ear through the cartilage lest a priest-slave be blemished (122:6; Kiddushin 21b:7, 21b:12; Bekhorot 37b:12-14): THE PARAMETER the_ear; the master who pierces the left ear barred from it", ['barred_from_it'])
    if ask == 'the_priests_ear':
        ink('15:17', '"and he shall be your servant for ever" — the priest\'s "he shall return to his family" Leviticus 21:? and the blemish list Leviticus 21:18 "blind or lame" %s' % (words('Lev', 21, 18)[9:12],))
        move('Kiddushin 21b:13-16, 21b:7 (read whole at the docket); Bekhorot 37b:12-14 (read whole at the docket); cold_run_priesthood (CALL) — PR.blemish(beast_unfits_in_man) = %s, PR.blemish(blemish_tokens) = %s' % (V(PR_UNFITS), V(PR_TOKENS)), "THE PRIEST'S SLAVE — for a priest-slave Rav permits the Canaanite maidservant and Shmuel forbids with Rav Nachman's proof (21b:13-16); NOT PIERCED lest he be blemished (21b:7 — the upper ear through the cartilage the rule's ground; Bekhorot 37b:12-14 the lentil for the slaughter against any hole for the altar): the priest's blemish by CALL (the blemish tokens five in the priest's file)")
        dat('the priest\'s ear a DATA row (the_priests_ear — Kiddushin 21b:7, 21b:13-16; Bekhorot 37b:12-14); the exam\'s person the priest\'s slave who says "I will not go out" — not pierced: exempt')
        return out("the priest's ear (15:17) — a priest-slave is not pierced lest he be blemished (Kiddushin 21b:7; Bekhorot 37b:12-14; the priest's blemish by CALL to priesthood.blemish); Rav and Shmuel on his Canaanite maidservant (21b:13-16): the priest's slave who says 'I will not go out' exempt from the piercing", ['exempt'])
    if ask == 'the_for_ever':
        ink('15:17', '"and he shall be your servant FOR EVER" — "servant for ever" in this form ONE seat %s; Exodus 21:6\'s "and he shall serve him for ever" %s; "for ever" (לעלם) the Torah\'s ten seats; Leviticus 25:10\'s "proclaim liberty" %s; Onkelos "a serving servant for ever"' % (FOR_EVER, P('ועבדו', 'לעלם'), P('וקראתם', 'דרור')))
        move('the Sifrei 122:8 (read whole at the reading); Kiddushin 15a:19-22, 21b:4, 17b:4-13 (read whole at the docket); Arakhin 33a:2-4, Bava Metzia 71a:14 (read whole at the docket); cold_run_yovel (CALL) — YO.jubilee() release_day = %s, YO.cycle(50) fx %s; cold_run_mishpatim (CALL) — the F1 row %s' % (V(YO_JUB['release_day']), YO_C50['fx'], MP_F1[2]), "'FOR EVER' THE MASTER'S LIFETIME — 'for ever' is said here and 'for ever' at Exodus 21:6 (122:8 — I2 named in the Hebrew on the word, checked in MIDDOT.md): until the jubilee (Kiddushin 15a:21-22; 21b:4 — the master's lifetime, the jubilee's forever; the two verses both needed 15a:19-20); THE JUBILEE FREES EVEN HIM — jubilee_release ON FILE by CALL to yovel ('the timer that overrides even the pierced slave's forever'; mishpatim's FREE-AT-JUBILEE row); THE PIERCED SERVES NO HEIR (17b:4-13 — the son stands in his father's place for the designation and the field, not the pierced; Bava Metzia 71a:14); the pierced slave's jubilee at Jeremiah's seat (Arakhin 33a:2-4)")
        dat('THE CASE\'S WRITE serves_for_ever — a STATUS on the pierced slave at the runner\'s own scene (never on the tape), its term the master\'s life; THE PARAMETER the_for_ever (the master\'s lifetime; the jubilee\'s override on file); the exam\'s person the pierced slave at his master\'s death — free; the pierced slave at the jubilee — free')
        return out("'for ever' (15:17) — the master's lifetime by I2 with Exodus 21:6 (the Sifrei 122:8; Kiddushin 15a:19-22, 21b:4), the jubilee freeing even him (jubilee_release on file by CALL to yovel), the pierced serving no heir (17b:4-13): THE PARAMETER the_for_ever; the pierced slave serves for ever — the master's life, the jubilee's override", ['serves_for_ever'])
    if ask == 'the_maidservant_never_pierced':
        ink('15:17', '"and ALSO TO YOUR MAIDSERVANT you shall do LIKEWISE" — the clause %s (one seat); Exodus 21:7 "she shall not go out as the menservants do" %s; "you shall do likewise" in the book %s (12:31 the other); "your maidservant" the book\'s five' % (P('ואף', 'לאמתך', 'תעשה', 'כן'), words('Exod', 21, 7)[-4:], P('תעשה', 'כן', books=DT)))
