    if ask == 'the_double_hire':
        ink('15:18', '"for DOUBLE THE HIRE OF A HIRELING he has served you six years" — "the hire of a hireling" %s (Malachi\'s oppressors the other); "hireling" the Torah\'s ten %s; "double" the Torah\'s seven %s (17:18\'s copy of the law the same word); Onkelos "two for one"' % (P('שכר', 'שכיר'), [s for s, _, _ in LEMT('7916', books=T)], [(s, x) for s, x, _ in LEMT('4932', books=T)]))
        move('the Sifrei 123:1-2 (read whole at the reading); the Mekhilta on Exodus 21:2 (its spine); Kiddushin 15a:11-13, 21b:13-16 (read whole at the docket); cold_run_holiness (CALL) — HO.wage(hire_kinds) = %s, (first_morning) = %s' % (V(HO_HIRE), V(HO_MORNING)), "THE DOUBLE HIRE — day and night: the night's service THE SIFREI'S READING (123:1 — a hireling by day, the slave by day and by night) AGAINST THE MEKHILTA'S: A DISPUTE OF TWO SPINES, two arms — RESOLVED AT THE DOCKET: THE NIGHT'S SERVICE IS THE CANAANITE MAIDSERVANT, NOT LABOR (Kiddushin 15a:11-13 — 'double the hire of a hireling': the master gives him a Canaanite maidservant, the offspring his; the priest-slave Rav permits and Shmuel forbids 21b:13-16); 'he has served you' — work, not idleness (123:2); the hireling's wage by CALL (the hire's kinds, the first morning)")
        dat('THE PARAMETER the_double_hire (123:1 — two spines; RESOLVED as data: the night\'s service the maidservant, Kiddushin 15a:11-13); the exam\'s person the master who gives the Hebrew slave a Canaanite maidservant — accepted (the night\'s service)')
        return out("the double hire (15:18) — 'double the hire of a hireling': the night's service — a dispute of two spines (the Sifrei 123:1 against the Mekhilta) RESOLVED at Kiddushin 15a:11-13: the Canaanite maidservant, not labor; work not idleness (123:2); the hireling's wage by CALL to holiness.wage: THE PARAMETER the_double_hire; the master who gives the Hebrew slave a Canaanite maidservant accepted", ['accepted'])
