        ink('15:18', '"IT SHALL NOT SEEM HARD to you when you send him away free … and the LORD your God will BLESS YOU in all that you do" — "hard" %s (1:17\'s judges the other); "in all that you do" %s (one seat in the book); the five blessing verses %s' % (U('יקשה'), P('בכל', 'אשר', 'תעשה', books=DT), [v for v in range(1, 24) if any(x in ('ברך', 'יברכך', 'ברכך', 'וברכך') for x in W15(v))]))
        move('the Sifrei 123:3 (read whole at the reading); cold_run_food_tithe (CALL) — FT.the_third_year(the_four_in_want) = %s' % (str(V(FT_FOUR))[:30],), "THE BLESSING BESIDE EVERY MONEY LOSS — 'it shall not seem hard to you … and the LORD your God will bless you': wherever the Torah takes money it gives the blessing beside it (123:3 — the gift to the needy at 15:10, the slave sent free at 15:18): work_of_the_hand_blessed's SECOND SEAT on the line hebrew_slave_law_declared (14:29's twin by CALL)")
